const job = $('Read Job').first()?.json || {};
const allRows = $('Read Qualified Entities').all().map(function(i) { return i.json; });
const entityType = ($('Set Vars').item.json.entity_type || 'lead').toString();
const resultMode = $('Set Vars').item.json.result_mode || 'scored';
const requestedCount = $('Set Vars').item.json.requested_count;

function isTrue(v) {
  return v === true || v === 'true' || v === 'TRUE' || v === 'True' || v === 1 || v === '1';
}
function isQualified(e) {
  const status = (e.status || '').toString().toLowerCase();
  return (status === 'qualified' || (Number(e.total_score) || 0) >= 60);
}
function acceptanceProofOk(e) {
  return (e.quality_decision === 'ACCEPT')
      && (e.region_status === 'MATCH')
      && isTrue(e.service_match)
      && (e.final_role === 'PRIVATE_DEMAND')
      && (e.freshness_status === 'CURRENT')
      && (e.actionability_status === 'ACTIONABLE');
}

if (entityType === 'tender') {
  function proofPass(e){ return !!(e.url && /^https?:\/\//.test(e.url)
    && e.atomic_status==='ATOMIC_TENDER'
    && ['FULL_PAGE','PROVIDER_CONTENT'].includes(e.evidence_status)
    && e.region_status==='MATCH' && e.region
    && e.freshness_status==='CURRENT' && isTrue(e.service_match)
    && e.source_excerpt); }
  const acceptedRows = allRows.filter(proofPass);
  acceptedRows.sort((a,b) => {
    const aq = isQualified(a)?0:1, bq=isQualified(b)?0:1;
    if (aq!==bq) return aq-bq;
    const sd = (Number(b.total_score)||0) - (Number(a.total_score)||0);
    if (sd!==0) return sd;
    return (a.title||'').localeCompare(b.title||'');
  });
  const reqNum = Number(requestedCount);
  const cap = Number.isFinite(reqNum) && reqNum > 0 ? reqNum : 30;
  const capped = acceptedRows.slice(0, cap);
  const qualifiedRows = acceptedRows.filter(isQualified);
  const avgQualified = qualifiedRows.length ? Math.round(qualifiedRows.reduce((s,r)=>s+(Number(r.total_score)||0),0)/qualifiedRows.length) : 0;
  const requestedDisplay = (Number.isFinite(reqNum) && reqNum>0) ? reqNum : null;
  const shortfall = requestedDisplay!=null ? Math.max(requestedDisplay - acceptedRows.length, 0) : null;
  const stats = { total_found: acceptedRows.length, accepted: acceptedRows.length, qualified: qualifiedRows.length, avg_score: avgQualified };
  return [{ json: { job: job, entities: capped, stats: stats, entity_type: entityType, is_zero_result: acceptedRows.length===0, qualified_count: qualifiedRows.length, accepted_count: acceptedRows.length, requested_count: requestedDisplay, shortfall: shortfall, result_mode: resultMode } }];
}

const qualified = allRows.filter(function(e) {
  const wf5Qualified = isQualified(e);
  if (!wf5Qualified) return false;
  if (entityType === 'lead') return acceptanceProofOk(e);
  return true;
});

var seen = {}; var unique = [];
for (var i = 0; i < qualified.length; i++) {
  var e = qualified[i]; var key = '';
  if (e.lead_id) key = 'lead:' + e.lead_id;
  else if (e.company_id) key = 'company:' + e.company_id;
  else if (e.tender_id) key = 'tender:' + e.tender_id;
  else if (e.source_url) key = 'url:' + e.source_url;
  else key = 'fallback:' + (e.title || '') + '|' + (e.source_url || '');
  if (!seen[key]) { seen[key] = true; unique.push(e); }
}

unique.sort(function(a, b) { return (Number(b.total_score) || 0) - (Number(a.total_score) || 0); });

var entities = unique;
if (requestedCount !== null && requestedCount !== undefined && requestedCount !== '') {
  const cap = Number(requestedCount);
  if (Number.isFinite(cap) && cap > 0) { entities = unique.slice(0, cap); }
}

const qualifiedCount = unique.length;
const acceptedRaw = Number($('Set Vars').item.json.accepted_count);
const acceptedCount =
  Number.isFinite(acceptedRaw) && acceptedRaw >= 0
    ? acceptedRaw
    : 0;
const isZeroResult = (resultMode === 'no_results') || (qualifiedCount === 0);
const avgScore = qualifiedCount ? Math.round(unique.reduce(function(s, e) { return s + (Number(e.total_score) || 0); }, 0) / qualifiedCount) : 0;
const stats = {
  total_found: acceptedCount,
  accepted: acceptedCount,
  qualified: qualifiedCount,
  avg_score: avgScore
};

return [{ json: { job: job, entities: entities, stats: stats, entity_type: entityType, is_zero_result: isZeroResult, qualified_count: qualifiedCount, accepted_count: acceptedCount, result_mode: resultMode } }];

const jobId = $('Set Vars').item.json.job_id || '';
const date = new Date().toISOString().slice(0,10);
const ctx = $('Prepare Context').first().json;
const stats = (ctx && ctx.stats) ? ctx.stats : {};
const accepted = (typeof stats.accepted === 'number') ? stats.accepted : 0;
const qualified = (typeof stats.qualified === 'number') ? stats.qualified : 0;
const avg = (typeof stats.avg_score === 'number') ? stats.avg_score : 0;
const md = '# OSINT Report

Дата: ' + date + '

## Сводка

После проверки ни одна заявка не квалифицирована.
Поисковые источники могли вернуть сырые кандидаты; этот отчёт не утверждает, что источники вернули 0 результатов.

Принято после проверки: ' + accepted + '
Квалифицировано: ' + qualified + '
Средний скор: ' + avg + '
';
return [{ json: { markdown_report: md } }];

// FAIL-CLOSED: WF6 MD to HTML — unified extraction (direct markdown_report OR DeepSeek response)
const item = $input.first();
const jobId = $('Set Vars').item.json.job_id || 'unknown';
if (!item || !item.json) {
  throw new Error('WF6_LLM_RESPONSE_INVALID — job_id=' + jobId + ' — no input');
}
let md = null;
if (typeof item.json.markdown_report === 'string') {
  md = item.json.markdown_report;
} else {
  const rawResponse = item.json;
  if (!rawResponse.choices || !Array.isArray(rawResponse.choices) || rawResponse.choices.length === 0) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — choices absent');
  }
  const content = rawResponse.choices[0]?.message?.content;
  if (!content || typeof content !== 'string' || content.trim() === '') {
    throw new Error('WF6_LLM_RESPONSE_INVALID — content empty');
  }
  let parsed;
  try {
    const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(clean);
  } catch(e) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — JSON parse failed');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('WF6_LLM_RESPONSE_INVALID — not object');
  }
  md = parsed.markdown_report;
}
if (!md || typeof md !== 'string' || md.trim() === '') {
  throw new Error('WF6_LLM_RESPONSE_INVALID — markdown empty');
}
function mdToHtml(s){
  let h = s;
  h = h.replace(/^### (.*)$/gm,'<h3>$1</h3>');
  h = h.replace(/^## (.*)$/gm,'<h2>$1</h2>');
  h = h.replace(/^# (.*)$/gm,'<h1>$1</h1>');
  h = h.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
  h = h.replace(/\*(.+?)\*/g,'<em>$1</em>');
  h = h.replace(/`([^`]+)`/g,'<code>$1</code>');
  h = h.replace(/^\|(.+)\|$/gm,(m)=>{const cells=m.slice(1,-1).split('|').map(c=>c.trim());return '<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>';});
  h = h.replace(/(<tr>[\s\S]+?<\/tr>)/g,'<table>$1</table>');
  h = h.replace(/^- (.*)$/gm,'<li>$1</li>');
  h = h.replace(/(<li>[\s\S]+?<\/li>)/g,'<ul>$1</ul>');
  h = h.replace(/\n\n/g,'</p><p>');
  return '<p>' + h + '</p>';
}
const body = mdToHtml(md);
const d = new Date().toISOString().slice(0,10);
const date = (item.json.report_date && typeof item.json.report_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(item.json.report_date)) ? item.json.report_date : d;
const html = '<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><title>OSINT ' + jobId + '</title><style>body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;max-width:800px;margin:40px auto;padding:20px;color:#222;line-height:1.6}h1{color:#1a365d;border-bottom:2px solid #1a365d;padding-bottom:8px}h2{color:#2c5282;margin-top:32px}h3{color:#2b6cb0}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{border:1px solid #ddd;padding:8px 12px;text-align:left}tr:nth-child(even){background:#f7fafc}code{background:#edf2f7;padding:2px 6px;border-radius:3px;font-family:SF Mono,Monaco,monospace}ul{padding-left:24px}.footer{margin-top:60px;padding-top:20px;border-top:1px solid #e2e8f0;color:#718096;font-size:12px}</style></head><body>' + body + '<div class="footer">OSINT Report Job: ' + jobId + ' Generated ' + date + '</div></body></html>';
return [{ json: { html: html, md: md, filename: 'OSINT_' + jobId + '_' + date + '.pdf', job_id: jobId, report_date: date } }];

