const ctx = $json;
const reportDate = new Date().toISOString().slice(0,10);
const requested = ctx.requested_count!=null ? ctx.requested_count : 'не задано';
const shortfall = ctx.shortfall!=null ? ctx.shortfall : 'не рассчитывается';
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function cell(s){ return esc(s).replace(/?
/g,' ').replace(/\|/g,'&#124;').replace(/\s+/g,' ').trim(); }
function safeUrl(u){ try { const p = new URL(u); if(['http:','https:'].includes(p.protocol)) return p.toString(); } catch(e){} return null; }
function validYMD(v){ if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v||''))) return false; const p=String(v).split('-').map(Number); const y=p[0],m=p[1],d=p[2]; const dt=new Date(Date.UTC(y,m-1,d)); return dt.getUTCFullYear()===y&&dt.getUTCMonth()+1===m&&dt.getUTCDate()===d; }
function money(n){ let v=n; if(v==null||v==='')return 'Не указана в доступном источнике'; if(typeof v==='string'){ let s=v.trim().replace(/[ \s]/g,'').replace(/,/g,'.'); const num=Number(s); v=Number.isFinite(num)?num:NaN; } else { v=Number(v); } if(!Number.isFinite(v)||v<=0) return 'Не указана в доступном источнике'; return Math.round(v).toLocaleString('ru-RU') + ' ₽'; }
function platformOf(e){ if(e.platform && String(e.platform).trim()) return String(e.platform).trim(); const u=String(e.url||''); try { const p=new URL(u); return p.hostname; } catch(err){ return ''; } }
function dateOrOpen(e){ if(validYMD(e.deadline)){ const p=String(e.deadline).split('-'); return p[2]+'.'+p[1]+'.'+p[0]; } if(e.freshness_status==='CURRENT') return 'Активен; точная дата не извлечена'; return 'Не указан'; }
function contactCell(e){ const parts=[e.contact_name,e.contact_phone,e.contact_email].filter(Boolean); return parts.length ? parts.join('; ') : 'Через площадку'; }
function sourceCell(e){ const u = safeUrl(e.url || e.source_url); if (!u) return 'Не указан'; const raw = String(u).replace(/[
]+/g, ''); const href = esc(raw.replace(/\|/g, '%7C')); const visible = esc(raw).replace(/\|/g, '&#124;'); return '<a href="' + href + '">Открыть карточку</a><br><span>' + visible + '</span>'; }
let md = '# Отчёт по тендерам

Дата: ' + reportDate + '

## Сводка

';
md += 'Запрошено: ' + requested + '
';
md += 'Принято после source verification: ' + ctx.accepted_count + '
';
md += 'Квалифицировано: ' + ctx.qualified_count + '
';
md += 'Дефицит до запроса: ' + shortfall + '
';
md += 'Средний скор квалифицированных: ' + (ctx.stats && ctx.stats.avg_score ? ctx.stats.avg_score : 0) + '

';
md += '## Тендеры

';
md += '|№|Название|Площадка|№ закупки|Заказчик|Регион|Сумма|Срок подачи|Score|Статус|Контакт / канал связи|Источник|
';
md += '|---|---|---|---|---|---|---|---|---|---|---|---|
';
(ctx.entities||[]).forEach((e,i) => {
  const platform = platformOf(e);
  md += '|'+(i+1)+'|'+cell(e.title||'Без названия')+'|'+cell(platform||'Не указана')+'|'+cell(e.tender_number||'Не указан')+'|'+cell(e.customer||'Не указан')+'|'+cell(e.region||'Не указан')+'|'+cell(money(e.budget))+'|'+cell(dateOrOpen(e))+'|'+(Number(e.total_score)||0)+'|'+cell(e.status||'new')+'|'+cell(contactCell(e))+'|'+sourceCell(e)+'|
';
});
md += '
## Детали топ-5

';
(ctx.entities||[]).slice(0,5).forEach((e,i) => {
  md += '### '+(i+1)+'. '+esc(e.title||'Без названия')+'

';
  md += 'Score: '+(Number(e.total_score)||0)+'

Статус: '+(e.status||'new')+'

';
  md += 'Почему релевантно: '+esc(e.why_relevant||'')+'

';
  md += 'Рекомендуемое действие: '+esc(e.recommended_action||'')+'

';
  md += 'Черновик первого сообщения: '+esc(e.first_message_draft||'')+'

';
  md += 'Источник: '+sourceCell(e)+'

';
});
return [{ json: { markdown_report: md, report_date: reportDate } }];
